import pytest

from bedrock_protocol import v1001, v2168, v2225

# TODO: confirm against BDS. gophertunnel writes CameraSplineDefinition.SplineType as Optional[string] and both
# key frames' easing as a bare string; the r26_u4 dump and SharedTypes/v1_26_0/camera/CameraSplineFileDefinition.h
# have a plain std::string mSplineType and std::optional<EasingType> mEasingType, so gophertunnel has to give: its
# spline-type presence byte is dropped and a presence byte is added before each easing name.
# generated by gophertunnel b8bd735:
# &packet.CameraSpline{Splines:
# []protocol.CameraSplineDefinition{{Name: "mypack:flyby", TotalTime: 2.5,
# SplineType: protocol.Option("catmullrom"), ControlPoints: []mgl32.Vec3{{1, 2, 3},
# {4, 5, 6}}, ProgressKeyFrames: []protocol.CameraProgressOption{{Value: 0.5,
# Time: 1.25, EaseType: protocol.EasingTypeInOutQuad}}, RotationKeyFrames:
# []protocol.CameraRotationOption{{Value: mgl32.Vec3{10, 20, 30}, Time: 2.5,
# EaseType: protocol.EasingTypeLinear}}}}}
# TODO: patched, confirm against BDS
FLYBY = bytes.fromhex(
    "010c6d797061636b3a666c796279000020400a6361746d756c6c726f6d020000803f0000004000004040000080400000a0400000c040010000003f0000a03f010b696e5f6f75745f7175616401000020410000a0410000f0410000204001066c696e656172"
)

# generated by gophertunnel b8bd735:
# &packet.CameraSpline{}
NO_SPLINES = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v2225.CameraSplinePacket(
            splines=[
                v2225.CameraSplineDefinition(
                    name="mypack:flyby",
                    total_time=2.5,
                    spline_type="catmullrom",
                    spline_control_points=[
                        v2225.CameraSplineControlPoint(position=v2225.Vec3(x=1.0, y=2.0, z=3.0)),
                        v2225.CameraSplineControlPoint(position=v2225.Vec3(x=4.0, y=5.0, z=6.0)),
                    ],
                    spline_progress_frames=[
                        v2225.CameraSplineProgressKeyFrame(
                            alpha=0.5, time_seconds=1.25, easing_type=v2225.EasingType.IN_OUT_QUAD
                        )
                    ],
                    spline_rotation_frames=[
                        v2225.CameraSplineRotationKeyFrame(
                            rotation=v2225.Vec3(x=10.0, y=20.0, z=30.0),
                            time_seconds=2.5,
                            easing_type=v2225.EasingType.LINEAR,
                        )
                    ],
                )
            ]
        ),
        FLYBY,
        id="flyby",
    ),
    pytest.param(v2225.CameraSplinePacket(), NO_SPLINES, id="no-splines"),
]


@pytest.fixture
def eased():
    return v2225.CameraSplinePacket(
        splines=[
            v2225.CameraSplineDefinition(
                name="mypack:flyby",
                total_time=1.0,
                spline_type="linear",
                spline_rotation_frames=[
                    v2225.CameraSplineRotationKeyFrame(
                        rotation=v2225.Vec3(x=0.0, y=0.0, z=0.0),
                        time_seconds=1.0,
                        easing_type=v2225.EasingType.LINEAR,
                    )
                ],
            )
        ]
    )


@pytest.fixture
def uneased():
    return v2225.CameraSplinePacket(
        splines=[
            v2225.CameraSplineDefinition(
                name="mypack:flyby",
                total_time=1.0,
                spline_type="linear",
                spline_rotation_frames=[
                    v2225.CameraSplineRotationKeyFrame(
                        rotation=v2225.Vec3(x=0.0, y=0.0, z=0.0), time_seconds=1.0, easing_type=None
                    )
                ],
            )
        ]
    )


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_camera_spline_is_packet_338(version):
    assert version.packets[338] is version.CameraSplinePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_spline_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_camera_spline_decodes_from_its_golden(packet, golden):
    assert v2225.CameraSplinePacket.from_bytes(golden) == packet


def test_an_absent_camera_spline_easing_is_seven_bytes_shorter_than_a_named_one(eased, uneased):
    assert len(bytes(uneased)) + 7 == len(bytes(eased))


def test_an_absent_camera_spline_easing_is_one_zero_byte(uneased):
    assert bytes(uneased)[-1] == 0


def test_an_absent_camera_spline_easing_round_trips(uneased):
    assert v2225.CameraSplinePacket.from_bytes(bytes(uneased)) == uneased
